entries[196460] = { ["name"] = "Verweilender Blick", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde konzentriert seinen Blick in einem astralen Auge und projiziert dies auf das Ziel. Sobald das Auge landet, ruft es einen Bereich verweilenden Blicks hervor. Spielercharaktere, die sich in dieser Zone aufhalten, erleiden pro Sekunde 13 Schattenschaden und werden verlangsamt." }
