entries[196467] = { ["name"] = "Steinbalgrosskopf", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGegerbtes Steinbalgleder (15)\nSteinbalglederrosskopf\nQuestgegenstand\nEinzigartig\n\"Rüstung für den Kopf eines Reittieres.\"" }
entries[196468] = { ["name"] = "Steinbalgcrinet", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGegerbtes Steinbalgleder (30)\nSteinbalgledercrinet\nQuestgegenstand\nEinzigartig\n\"Rüstung für den Hals eines Reittieres.\"" }
entries[196469] = { ["name"] = "Steinbalgschabracke", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGegerbtes Steinbalgleder (50)\nSteinbalglederschabracke\nQuestgegenstand\nEinzigartig\n\"Rüstung für den Körper eines Reittieres.\"" }
entries[196470] = { ["name"] = "Violettglasgefäß", ["text"] = "Wirken in 2 sek. 5\nDie Vorliebe der Hochgeborenen für die Farbe Violett gab es bereits vor dem Krieg der Ahnen. Glasschüsseln waren sehr gebräuchlich und wurden für die Aufbewahrung von allem von Getreide bis Goldbarren genutzt." }
entries[196471] = { ["name"] = "Inaktiver Leysteinglücksbringer", ["text"] = "Wirken in 2 sek. 5\nViele Hochgeborenen trugen abergläubisch kleine Stücke Leystein als Glücksbringer bei sich. Solche Amulette wurden zumeist von Bauern getragen, überarbeiteten Studenten der Akademie oder jenen auf der dünnen Schneide zwischen reichem Bürgertum und Adel." }
entries[196472] = { ["name"] = "Stillrebenphiole", ["text"] = "Wirken in 2 sek. 5\n\"Stillrebe\" ist ein uraltes Wort der Hochgeborenen für \"Gift\". Ironischerweise verliert die Substanz nach zehntausend Jahren im Erdreich für gewöhnlich ihre tödliche Wirkung und wird zu einem milden Rauschmittel." }
entries[196473] = { ["name"] = "Vorkriegswandschmuck der Hochgeborenen", ["text"] = "Wirken in 2 sek. 5\nBei Wandteppichen, die vor Königin Azsharas Pakt mit den Dämonen gewoben wurden, findet man üblicherweise eine einzigartige Stickerei vor, deren Stiche parallel zum Fadenlauf über zwei Querfäden laufen. Diese Technik sucht man seitdem vergeblich." }
entries[196474] = { ["name"] = "Brieföffner eines Adligen", ["text"] = "Wirken in 2 sek. 5\nWie es für Brieföffner für gewöhnlich der Fall ist, ein komplett nutzloses Werkzeug, das allein darin Berechtigung findet, um in Fällen, in denen es gesellschaftlich inakzeptabel wäre, einen Dolch bei sich zu tragen, eine Mordwaffe bei der Hand zu haben." }
entries[196475] = { ["name"] = "Trommel des Aufbruchs", ["text"] = "Wirken in 2 sek. 5\nNicht alle Hochbergtauren sind Jäger, doch die, die diesen Pfad beschreiten, gedenken ihrer ersten Beute üblicherweise, indem sie sich aus dessen Haut eine zeremonielle Trommel fertigen. Die meisten Trommeln des Aufbruchs bestehen aus Hasen- oder Fuchshaut. Gemäß den alten Bräuchen tragen Jäger sie ihr ganzes Leben lang." }
entries[196476] = { ["name"] = "Angelhaken aus Elchknochen", ["text"] = "Wirken in 2 sek. 5\nElchknochen waren zu jener Zeit das üblichste Material für Angelhaken: fest genug, um einen Haken daraus zu schnitzen, jedoch nachgiebig genug, um im Maul eines großen Lachses nicht zu zerbrechen. Viele Fischer schnitzten aufwendige Muster in ihre \"Glückshaken\"." }
entries[196477] = { ["name"] = "Handgeschliffener Pyrostein", ["text"] = "Wirken in 2 sek. 5\nFür die Hinterbliebenen war es üblich, einen Stein von der Feuerbestattung eines besonders geliebten Verstorbenen zu bewahren. Diese Steine trägt man in einer Tasche bei sich und reibt sie, um Mut oder Trost zu erhalten oder sich an den verlorenen Gefährten zu erinnern." }
entries[196478] = { ["name"] = "Edelsteinschleifer der Drogbar", ["text"] = "Wirken in 2 sek. 5\nWährend die meisten Drogbar die rauen Kanten ungeschliffener Edelstein schätzten, bevorzugten andere glattere, rundere Juwelen. Anstatt gewöhnliche Methoden zum Schleifen von Edelsteinen zu nutzen, waren handbetriebene Steintrommeln üblich, die die Edelsteine im Verlauf von mehreren Wochen abrundeten. Diese wurden normalerweise von Dienern, Sklaven oder unfolgsamen Jugendlichen bedient." }
entries[196479] = { ["name"] = "Steinholzbogen", ["text"] = "Wirken in 2 sek. 5\nDer Bogen ist aus einem steinhartem Baumholz gefertigt, was es beinahe unmöglich macht, ihn zu spannen. Die Archäologen sind sich noch uneins, ob der Bogen ursprünglich so hart war oder ob das Holz über die Zeit einfach versteinert ist. Ungeachtet dessen weisen Größe und Gewicht des Bogens darauf hin, dass er nur von sehr geübten Taurenjägern genutzt worden sein konnte." }
entries[196480] = { ["name"] = "Wichtelkelch", ["text"] = "Wirken in 2 sek. 5\nAuch Wichtel müssen trinken, und die meisten bevorzugen es, ihren eigenen Becher bei sich zu haben. Es gibt Theorien, dass ein uraltes wichtelartiges Volk ihre Trinkgefäße als etwas Heiliges verehrten. Ein Teil dieses Rituals überdauerte selbst die Indoktrination durch die Brennende Legion." }
entries[196481] = { ["name"] = "Auf Haut geschriebene Chronik", ["text"] = "Wirken in 2 sek. 5\nVerschiedene Arten von Dämonen zeigen zwischen ihren Kämpfen verschiedene Verhaltensweisen. Sukkubi zum Beispiel haben eine Tendenz, detaillierte Tagebücher zu führen. Ihre Erzählungen sind oft blutrünstig, fast immer grotesk und üblicherweise auf Pergament geschrieben, das aus der Haut von Feinden oder Gefangenen gefertigt wurde." }
entries[196482] = { ["name"] = "Deformierter Abyssal", ["text"] = "Wirken in 2 sek. 5\nDas Ritual zur Beschwörung eines Abyssals ist kompliziert und schlägt häufig fehl. Bei einem Fehlschlag bleibt oft ein kleines Stück des Dämons zurück, das mit einer Mischung aus dämonischem Zorn und Verzweiflung ob seiner eigenen Unfähigkeit schwelt. Alte Schlachtfelder sind mit solchen Steinen übersät." }
entries[196483] = { ["name"] = "Kugel des inneren Chaos", ["text"] = "Wirken in 2 sek. 5\nDas Chaos ist nicht für alle Dämonen ein einfach umzusetzendes Konzept. Einige taten sich mit der Art der Brennenden Legion schwer. Jene, denen es so erging, trugen oft eine verzauberte Kugel bei sich, die den Zorn hervorrief, der von einem guten Dämon erwartet wurde. Es ist nicht bekannt, wie oder von wem die Kugeln erschaffen wurden." }
entries[196484] = { ["name"] = "Hundebisshalsberge", ["text"] = "Wirken in 2 sek. 5\nEin massives Stück \"Kettenrüstung\", komplett aus den Zähnen dämonischer Hunde hergestellt. Die Spitzen der Zähne zeigen nach oben und innen, sodass es unmöglich ist, die Rüstung auszuziehen, wenn sie einmal angelegt wurde. Genauer gesagt ist dies unmöglich, ohne die Haut ihres Trägers abzuziehen." }
