entries[196487] = { ["name"] = "Geläuterte Erneuerung", ["text"] = "Wenn schädliche Effekten durch 'Läutern' entfernt werden, wird das Ziel mit dem Effekt 'Geläuterte Erneuerung' belegt, der es sofort um (6.875% der Zaubermacht) Gesundheit sowie im Verlauf von 8 Sek. um zusätzlich 16 Gesundheit heilt." }
