entries[196512] = { ["name"] = "Klauenzorn", ["text"] = "Wirken in 1 sek. 2 sek. Abklingzeit\nFenryr greift wild an und fügt allen Gegnern innerhalb von 12 Metern 20607820 körperlichen Schaden zu, der unter allen Zielen aufgeteilt wird.\n\nDieser Angriff trifft immer und ignoriert Rüstung." }
