entries[196528] = { ["name"] = "Knochensturm", ["text"] = "Sofort\nVerbraucht bis zu 5 Aufladungen von 'Knochenschild', um einen Wirbel aus Knochen und Blut zu erzeugen, der auf alle Gegner in der Nähe eindrischt, ihnen alle 1 Sek. (28.25% der Angriffskraft) Schattenschaden zufügt und Euch jedes Mal, wenn dieser Effekt Schaden verursacht, um 2% Eurer maximalen Gesundheit heilt (bis zu 10%). Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nHält pro verbrauchter Aufladung von 'Knochenschild' 2 Sek. lang an und regeneriert alle 1 Sek. schnell eine Aufladung." }
