entries[196742] = { ["name"] = "Wirbelnder Drachenschlag", ["text"] = "Sofort\nEntfesselt einen vernichtenden, wirbelnden Aufwärtsschlag, der allen Gegnern in der Nähe [3 * (161% der Angriffskraft)] Schaden sowie dem ersten getroffenen Ziel zusätzlich (300% der Angriffskraft) Schaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\nKann nur eingesetzt werden, während sich sowohl 'Furorfäuste' als auch 'Tritt der aufgehenden Sonne' in der Abklingzeit befinden." }
entries[196743] = { ["name"] = "Chiorbit", ["text"] = "Alle 5 Sek. bildet sich eine Energiekugel, die um Euch kreist, bis sie auf einen Gegner trifft. Die Kugel fügt ihm dann (24.57% der Angriffskraft) Schaden zu. Maximal 4 Kugeln." }
