entries[196749] = { ["name"] = "Ölfleck", ["text"] = "100 Meter Reichweite\nSofort\nErzeugt einen Ölfleck hinter der Zaubernden. Gegner, die den Ölfleck betreten, werden verlangsamt, solange sie versuchen, sich hindurchzubewegen." }
